UPDATE Receipts.Batch SET AmountReceived = (SELECT (CAST(TotalCreditDollarAmount AS money))/100 FROM Receipts.EBOXFileControl WHERE BatchId = @BatchId), 
AccountsReceived = (SELECT SUM(CAST(EntryCount AS INT)) FROM Receipts.EBOXFileControl WHERE BatchId = @BatchId) 
,[FileType] = @BatchId,[Source] = (SELECT DISTINCT SOURCE FROM  Receipts.EBOXFileHeader WHERE BatchId=@gv_getFileType) WHERE BatchId = @BatchId;
